import csv, collections, datetime as dt
series = {
 'F2_zone_cool_sp':'1213f3a8-c23d-55b5-8187-4712d49a82ae',
 'F3_zone_cool_sp':'5b98cbc1-fd25-5d8c-a96e-c3de49819174',
}
id2name={v:k for k,v in series.items()}
data = collections.defaultdict(dict)
with open(VALUES_CSV) as f:
    r=csv.reader(f); next(r)
    for row in r:
        tid,ts,val=row[0],row[1],row[2]
        if tid in id2name: data[id2name[tid]][ts]=float(val)

# Look at hourly pattern over one day in Jan 2018 and same day in Aug 2018
for label, prefix in [('Jan', '2018-01-15'), ('Aug', '2018-08-15')]:
    print(label)
    for h in range(24):
        t=f"{prefix}T{h:02d}:00:00"
        if t in data['F2_zone_cool_sp']:
            print("  h",h, "F2", data['F2_zone_cool_sp'][t], "F3", data['F3_zone_cool_sp'].get(t))

# Distinct setpoint values in F2 before and after mid-June
def before_t(t): return dt.datetime.fromisoformat(t) < dt.datetime(2018,6,15)
b=collections.Counter(data['F2_zone_cool_sp'][t] for t in data['F2_zone_cool_sp'] if before_t(t))
a=collections.Counter(data['F2_zone_cool_sp'][t] for t in data['F2_zone_cool_sp'] if not before_t(t))
print("F2 sp values before:", b)
print("F2 sp values after:", a)
b3=collections.Counter(data['F3_zone_cool_sp'][t] for t in data['F3_zone_cool_sp'] if before_t(t))
a3=collections.Counter(data['F3_zone_cool_sp'][t] for t in data['F3_zone_cool_sp'] if not before_t(t))
print("F3 sp values before:", b3)
print("F3 sp values after:", a3)
